{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Efficacy and effectiveness of COVID-19 vaccines against SARS-CoV-2 infection: interim results of a living systematic review, 1 January to 14 May 2021",
      "reason": "The title explicitly identifies the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Efficacy and effectiveness of COVID-19 vaccines against SARS-CoV-2 infection",
      "reason": "The title states the intervention (COVID-19 vaccines) and the outcome/population focus (SARS-CoV-2 infection), conveying the main objective of the review."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "interim results of a living systematic review, 1 January to 14 May 2021",
      "reason": "The title provides supplementary information on review status (living, interim results) and the covered time period."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "All vaccines approved by the European Medical Agency (EMA) at the time of writing demonstrated high vaccine efficacy/effectiveness (VE) against severe COVID-19.",
      "reason": "The introduction describes the current state of knowledge (high VE against severe disease) and the uncertainty about preventing symptomatic/asymptomatic infection."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "With vaccination programmes being implemented in most European countries, it becomes urgent to assess the extent to which these vaccines are also able to prevent symptomatic and asymptomatic infections to guide public health recommendations and develop strategies for fully vaccinated people.",
      "reason": "The importance and urgency of the review are explicitly explained in the context of public health needs."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_1",
      "quote": "In December 2020, the Robert Koch Institute (RKI)... initiated a living systematic review on the VE and safety of European Union (EU)-licensed COVID-19 vaccines (PROSPERO registration: CRD42020208935).",
      "reason": "The manuscript presents itself as a new living systematic review with a PROSPERO-registered protocol; no prior similar systematic review is identified as being updated or replicated, so this conditional element does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of intervention effects (COVID-19 vaccines), but no mechanism of action of the vaccines is described anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review evaluates vaccine efficacy/effectiveness, which is not a complex intervention or complex delivery context; no logic model requirement applies."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "In detail, we report the interim results of the review focusing on two research questions: What is the efficacy/effectiveness of COVID-19 vaccines in preventing SARS-CoV-2 infections (irrespective",
      "reason": "The manuscript explicitly states the review's research questions in the introduction/objectives text, framed around vaccine efficacy/effectiveness against SARS-CoV-2 infection."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "We considered studies of any design as long as they had a comparison group that investigated VE against SARS-CoV-2 infection and/or asymptomatic SARS-CoV-2 infection after vaccination with an EMA-approved COVID-19 vaccine (see Supplement Part S2 for complete population intervention comparison outcomes (PICO) questions)",
      "reason": "PICO questions are referenced but the complete planned comparisons are deferred to a supplement; only partial PICO elements (population, intervention, comparison implied) are stated in the main text."
    }
  ],
  "confidence": 85
}

{
